import React, { useEffect, useMemo, useState } from "react";
import Navbar from "../../components/Navbar";
import { api, API_BASE } from "../../utils/api";

export default function AdminDashboard() {
  const [loading, setLoading] = useState(false);

  const [cases, setCases] = useState([]);
  const [users, setUsers] = useState([]);

  const [selected, setSelected] = useState(null);

  const [statusFilter, setStatusFilter] = useState("ALL");
  const [severityFilter, setSeverityFilter] = useState("ALL");
  const [search, setSearch] = useState("");

  const [replyDraft, setReplyDraft] = useState("");
  const [notesDraft, setNotesDraft] = useState("");

  // 🤖 AI states
  const [aiLoading, setAiLoading] = useState(false);
  const [aiData, setAiData] = useState(null);

  async function loadCases() {
    const res = await api.get("/api/admin/cases", {
      params: {
        status: statusFilter,
        severity: severityFilter,
        q: search
      }
    });
    setCases(res.data || []);
  }

  async function loadUsers() {
    const res = await api.get("/api/admin/users");
    setUsers(res.data || []);
  }

  async function init() {
    setLoading(true);
    try {
      await Promise.all([loadCases(), loadUsers()]);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    init();
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    loadCases();
    // eslint-disable-next-line
  }, [statusFilter, severityFilter]);

  const selectedCase = useMemo(() => {
    if (!selected) return null;
    return cases.find((c) => c._id === selected) || null;
  }, [selected, cases]);

  useEffect(() => {
    if (selectedCase) {
      setReplyDraft(selectedCase.analystReply || "");
      setNotesDraft(selectedCase.internalNotes || "");
      setAiData(null);
    } else {
      setReplyDraft("");
      setNotesDraft("");
      setAiData(null);
    }
  }, [selectedCase]);

  async function openCase(id) {
    setSelected(id);
  }

  async function updateSelectedCase(patch) {
    if (!selectedCase) return;

    const res = await api.patch(`/api/admin/cases/${selectedCase._id}`, patch);

    // update local list
    setCases((prev) =>
      prev.map((c) => (c._id === selectedCase._id ? res.data : c))
    );
  }

  async function saveReplyAndNotes() {
    if (!selectedCase) return;

    await updateSelectedCase({
      analystReply: replyDraft,
      internalNotes: notesDraft
    });

    alert("Reply saved ✅");
  }

  async function searchNow() {
    await loadCases();
  }

  // 🤖 AI Suggest Reply
  async function aiSuggest() {
    if (!selectedCase) return;

    setAiLoading(true);
    setAiData(null);

    try {
      const res = await api.get(
        `/api/admin/cases/${selectedCase._id}/ai-suggest`
      );

      setAiData(res.data);

      // Auto apply AI suggestion into UI (not saved yet)
      if (res.data?.autoReply) setReplyDraft(res.data.autoReply);

      // Auto update status + severity in DB directly
      if (res.data?.status || res.data?.severity) {
        await updateSelectedCase({
          status: res.data.status,
          severity: res.data.severity
        });
      }
    } catch (err) {
      console.log(err);
      alert("AI suggest failed ❌");
    } finally {
      setAiLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-6xl mx-auto px-4 py-10">
        <h1 className="text-4xl font-black">SOC Dashboard</h1>
        <p className="text-gray-600 mt-1">
          Manage scam reports, reply to users, and track severity.
        </p>

        {/* Filters */}
        <div className="mt-6 flex flex-wrap gap-3 items-center">
          <select
            className="border rounded-2xl px-4 py-3 bg-white"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            <option value="ALL">ALL</option>
            <option value="NEW">NEW</option>
            <option value="SAFE">SAFE</option>
            <option value="SUSPICIOUS">SUSPICIOUS</option>
            <option value="SCAM">SCAM</option>
            <option value="CLOSED">CLOSED</option>
          </select>

          <select
            className="border rounded-2xl px-4 py-3 bg-white"
            value={severityFilter}
            onChange={(e) => setSeverityFilter(e.target.value)}
          >
            <option value="ALL">ALL</option>
            <option value="LOW">LOW</option>
            <option value="MEDIUM">MEDIUM</option>
            <option value="HIGH">HIGH</option>
          </select>

          <input
            className="border rounded-2xl px-4 py-3 flex-1 min-w-[260px]"
            placeholder="Search (ticket/name/phone/suspect)"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />

          <button
            className="px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold"
            onClick={searchNow}
            disabled={loading}
          >
            Search
          </button>
        </div>

        {/* Layout */}
        <div className="mt-8 grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Cases list */}
          <div className="bg-white rounded-3xl shadow p-5">
            <div className="font-black text-xl">Cases</div>

            <div className="mt-4 space-y-3">
              {cases.map((c) => (
                <button
                  key={c._id}
                  className={`w-full text-left rounded-2xl border p-4 hover:bg-gray-50 ${
                    selected === c._id ? "border-gray-900" : ""
                  }`}
                  onClick={() => openCase(c._id)}
                >
                  <div className="flex justify-between items-center">
                    <div className="font-black">{c.ticketId}</div>
                    <div className="text-xs font-bold">
                      {c.status} • {c.severity}
                    </div>
                  </div>

                  <div className="text-sm text-gray-600 mt-1">
                    {c.fullName} • {c.phone}
                  </div>

                  <div className="text-xs text-gray-500 mt-1">
                    {new Date(c.createdAt).toLocaleString()}
                  </div>
                </button>
              ))}

              {cases.length === 0 && (
                <div className="text-gray-600 mt-3">No cases found.</div>
              )}
            </div>
          </div>

          {/* Case details */}
          <div className="bg-white rounded-3xl shadow p-5">
            {!selectedCase ? (
              <div className="text-gray-600">
                Select a case to view details.
              </div>
            ) : (
              <>
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <div className="text-2xl font-black">
                      {selectedCase.ticketId}
                    </div>
                    <div className="text-sm text-gray-600 mt-1">
                      {selectedCase.fullName} • {selectedCase.phone} •{" "}
                      {selectedCase.category}
                    </div>
                  </div>

                  <div className="flex gap-2">
                    <select
                      className="border rounded-2xl px-3 py-2"
                      value={selectedCase.status}
                      onChange={(e) =>
                        updateSelectedCase({ status: e.target.value })
                      }
                    >
                      <option value="NEW">NEW</option>
                      <option value="SAFE">SAFE</option>
                      <option value="SUSPICIOUS">SUSPICIOUS</option>
                      <option value="SCAM">SCAM</option>
                      <option value="CLOSED">CLOSED</option>
                    </select>

                    <select
                      className="border rounded-2xl px-3 py-2"
                      value={selectedCase.severity}
                      onChange={(e) =>
                        updateSelectedCase({ severity: e.target.value })
                      }
                    >
                      <option value="LOW">LOW</option>
                      <option value="MEDIUM">MEDIUM</option>
                      <option value="HIGH">HIGH</option>
                    </select>
                  </div>
                </div>

                <div className="mt-5 border rounded-2xl p-4">
                  <div className="font-bold">User Message</div>
                  <div className="text-sm text-gray-800 mt-2 whitespace-pre-wrap">
                    {selectedCase.message}
                  </div>

                  {selectedCase.suspectNumber && (
                    <div className="text-sm mt-3">
                      <b>Suspect Number:</b> {selectedCase.suspectNumber}
                    </div>
                  )}

                  {selectedCase.link && (
                    <div className="text-sm mt-2">
                      <b>Link:</b>{" "}
                      <a
                        href={selectedCase.link}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-600 underline"
                      >
                        {selectedCase.link}
                      </a>
                    </div>
                  )}

                  {selectedCase.screenshotUrl && (
                    <div className="mt-4">
                      <div className="font-semibold text-sm">Screenshot:</div>
                      <img
                        alt="screenshot"
                        className="mt-2 rounded-2xl border w-full max-w-[520px] object-contain bg-white"
                        src={`${API_BASE}${selectedCase.screenshotUrl}`}
                      />
                      <a
                        href={`${API_BASE}${selectedCase.screenshotUrl}`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-600 underline text-sm mt-2 inline-block"
                      >
                        Open Screenshot
                      </a>
                    </div>
                  )}
                </div>

                {/* 🤖 AI Suggest Box */}
                <div className="mt-6 border rounded-2xl p-4 bg-gray-50">
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <div className="font-black text-lg">🤖 AI Suggest</div>
                      <div className="text-sm text-gray-600">
                        Auto generates status + reply (you can edit).
                      </div>
                    </div>

                    <button
                      onClick={aiSuggest}
                      disabled={aiLoading}
                      className="px-5 py-3 rounded-2xl bg-blue-600 text-white font-semibold disabled:opacity-60"
                    >
                      {aiLoading ? "Analyzing..." : "AI Suggest Reply"}
                    </button>
                  </div>

                  {aiData && (
                    <div className="mt-4 text-sm">
                      <div>
                        <b>Status:</b> {aiData.status} • <b>Severity:</b>{" "}
                        {aiData.severity}
                      </div>
                      <div className="mt-1 text-gray-600">
                        Confidence: <b>{aiData.confidence}%</b> • Score:{" "}
                        <b>{aiData.score}</b>
                      </div>
                    </div>
                  )}
                </div>

                {/* Reply (WhatsApp/Email style) */}
                <div className="mt-6 border rounded-2xl p-4">
                  <div className="font-black text-lg">Reply to User</div>
                  <p className="text-sm text-gray-600 mt-1">
                    This reply will be visible to the user in their portal.
                  </p>

                  <textarea
                    className="mt-4 w-full border rounded-2xl px-4 py-3 min-h-[140px]"
                    placeholder="Type reply here..."
                    value={replyDraft}
                    onChange={(e) => setReplyDraft(e.target.value)}
                  />

                  <div className="mt-3 font-semibold text-sm">
                    Internal Notes (SOC only)
                  </div>
                  <textarea
                    className="mt-2 w-full border rounded-2xl px-4 py-3 min-h-[90px]"
                    placeholder="Internal notes..."
                    value={notesDraft}
                    onChange={(e) => setNotesDraft(e.target.value)}
                  />

                  <button
                    className="mt-4 px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold"
                    onClick={saveReplyAndNotes}
                  >
                    Save Reply
                  </button>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Users table */}
        <div className="mt-10 bg-white rounded-3xl shadow p-5">
          <div className="font-black text-xl">Users</div>

          <div className="mt-4 overflow-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-gray-500">
                  <th className="py-2">Name</th>
                  <th>Email</th>
                  <th>Role</th>
                  <th>Status</th>
                  <th>Created</th>
                </tr>
              </thead>

              <tbody>
                {users.map((u) => (
                  <tr key={u._id} className="border-t">
                    <td className="py-3 font-semibold">{u.name}</td>
                    <td>{u.email}</td>
                    <td>{u.role}</td>
                    <td>{u.isActive ? "Active" : "Disabled"}</td>
                    <td>{new Date(u.createdAt).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            {users.length === 0 && (
              <div className="text-gray-600 mt-3">No users found.</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
